CustomField.formula:
IF(
!ISBLANK(TEXT( Source_Detail_Inquiry__c )), TEXT( Source_Detail_Inquiry__c ),
 IF(
  !ISBLANK( Source_Detail_Referral__c ), Source_Detail_Referral__r.FirstName  & ' ' & Source_Detail_Referral__r.LastName,
   IF(
    !ISBLANK( Source_Detail_Text__c ),  Source_Detail_Text__c,
     IF(
      !ISBLANK( Source_Detail_URL__c ),  Source_Detail_URL__c , NULL
       )
     )
   )
)
